import{describe,it,expect}from"vitest";import{FREEDOM_FIGHTERS_DATA,filterFreedomFighters}from"../../frontend/freedom-fighters-hub/script.js";describe("Freedom Fighters Knowledge Hub",()=>{it("should contain a complete dataset of prominent freedom fighters",()=>{expect(Array.isArray(FREEDOM_FIGHTERS_DATA)).toBe(!0),expect(FREEDOM_FIGHTERS_DATA.length).toBeGreaterThanOrEqual(8),FREEDOM_FIGHTERS_DATA.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("name"),expect(e).toHaveProperty("title"),expect(e).toHaveProperty("lifespan"),expect(e).toHaveProperty("era"),expect(e).toHaveProperty("region"),expect(e).toHaveProperty("birthplace"),expect(e).toHaveProperty("movements"),expect(Array.isArray(e.movements)).toBe(!0),expect(e).toHaveProperty("biography"),expect(e).toHaveProperty("timeline"),expect(Array.isArray(e.timeline)).toBe(!0),expect(e).toHaveProperty("contributions"),expect(e).toHaveProperty("rareFacts"),expect(e).toHaveProperty("quote")})}),it("should filter freedom fighters by search term",()=>{const e=filterFreedomFighters(FREEDOM_FIGHTERS_DATA,"Subhas");expect(e.length).toBe(1),expect(e[0].title).toBe("Netaji");const t=filterFreedomFighters(FREEDOM_FIGHTERS_DATA,"Quit India");expect(t.length).toBeGreaterThan(0)}),it("should filter freedom fighters by era",()=>{const e=filterFreedomFighters(FREEDOM_FIGHTERS_DATA,"","Revolutionary","all");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.era).toBe("Revolutionary"))}),it("should filter freedom fighters by region",()=>{const e=filterFreedomFighters(FREEDOM_FIGHTERS_DATA,"","all","East");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.region).toBe("East"))})});